"""ViPNet OSSL — белый перечень по таблицам импорта.

Утилита пакета IDA Batch Tool: проходит по готовым базам IDA (.i64/.idb),
читает ТОЛЬКО таблицы импорта, объединяет функции из всех баз, убирает
повторы и делит результат на две группы:

  * «белые» функции — есть в справочнике ViPNet OSSL 5.6;
  * функции OpenSSL 1.1.1w вне белого перечня — требуют доп. исследования.

Откуда берутся импорты:
  1. если рядом с базой есть <база>.export.json (артефакт «Анализа ПО») —
     импорты берутся из него, IDA не запускается;
  2. иначе база копируется во временный каталог и открывается в IDA
     лёгким скриптом, который выгружает только таблицу импорта.
     Оригинальная база при этом не изменяется.

Запуск:
    python vipnet_ossl_whitelist.py                      # графический интерфейс
    python vipnet_ossl_whitelist.py <папка> --out r.html # пакетный режим
    python vipnet_ossl_whitelist.py --self-test          # самопроверка
    python vipnet_ossl_whitelist.py --rebuild-data --crypto <dll> --ssl <dll> --pdf <pdf>

Словари внутри файла:
    OSSL_API  — экспорты собранных libcrypto/libssl OpenSSL 1.1.1w;
    WHITELIST — функции справочника ViPNet OSSL 5.6.

Требования: Python 3.9+ с tkinter (для GUI). Сторонние пакеты не нужны.
"""
from __future__ import annotations

import argparse
import concurrent.futures
import datetime as _dt
import html
import json
import os
import queue
import re
import shutil
import struct
import subprocess
