APP_TITLE = "ViPNet OSSL — белый перечень по импортам"
DB_SUFFIXES = (".i64", ".idb")
JSON_SUFFIX = ".export.json"
DEFAULT_JOBS = 4

# IDAPython-скрипт: выгружает только таблицу импорта в JSON.
_IDA_IMPORTS_SCRIPT = """\
import ida_auto
import ida_nalt
import idc
import json

ida_auto.auto_wait()
out_path = idc.ARGV[-1]
modules = {}
for idx in range(ida_nalt.get_import_module_qty()):
    module = ida_nalt.get_import_module_name(idx) or "unknown"
    bucket = modules.setdefault(module, [])

    def callback(ea, name, ordinal, _bucket=bucket):
        if name:
            _bucket.append(name)
        return True

    ida_nalt.enum_import_names(idx, callback)

with open(out_path, "w", encoding="utf-8") as handle:
    json.dump(modules, handle, ensure_ascii=False)
idc.qexit(0)
"""


# --- Нормализация имён ----------------------------------------------------

_IMPORT_PREFIX_RE = re.compile(r"^(?:__imp_|_imp__)")
_STDCALL_SUFFIX_RE = re.compile(r"@\d+$")


def normalize_symbol(name: str) -> str:
    """Приводит импортируемое имя к виду словарей.

    Снимает ``__imp_`` (MSVC), версию символа ELF (``SSL_new@OPENSSL_1_1_0``)
    и stdcall-суффикс (``_foo@8``).
    """
    result = name.strip()
    result = _IMPORT_PREFIX_RE.sub("", result)
    if "@" in result:
        result = result.split("@", 1)[0]
    result = _STDCALL_SUFFIX_RE.sub("", result)
    return result


# --- Сбор импортов --------------------------------------------------------


@dataclass
class ImportedSymbol:
    """Функция, импортируемая хотя бы одной базой."""

    name: str
    modules: set[str] = field(default_factory=set)
    databases: set[str] = field(default_factory=set)

    @property
    def count(self) -> int:
        return len(self.databases)


@dataclass
class UnitInfo:
    """Обработанная база (или осиротевший export.json)."""

    path: Path
    source: str  # "json" | "ida" | "error"
    imports: int = 0
    error: str = ""


@dataclass
class ImportScan:
    root: Path
    units: list[UnitInfo] = field(default_factory=list)
    symbols: dict[str, ImportedSymbol] = field(default_factory=dict)

    @property
    def json_units(self) -> int:
        return sum(1 for u in self.units if u.source == "json")

    @property
    def ida_units(self) -> int:
        return sum(1 for u in self.units if u.source == "ida")

    @property
    def errors(self) -> list[UnitInfo]:
        return [u for u in self.units if u.source == "error"]

    def _classify(self, name: str) -> str:
        if name in WHITELIST:
            return "white"
        if name in OSSL_API:
            return "nonwhite"
        return "other"

    @property
    def white(self) -> dict[str, ImportedSymbol]:
        return {n: s for n, s in self.symbols.items() if self._classify(n) == "white"}

    @property
    def non_white(self) -> dict[str, ImportedSymbol]:
        return {n: s for n, s in self.symbols.items() if self._classify(n) == "nonwhite"}

    @property
    def module_rows(self) -> list[tuple[str, int, int, int, int]]:
        """(модуль, импортов, белых, вне перечня, прочих) по убыванию импортов."""
        rows: list[tuple[str, int, int, int, int]] = []
        for module, names in self._module_names.items():
            white = sum(1 for n in names if self._classify(n) == "white")
            nonwhite = sum(1 for n in names if self._classify(n) == "nonwhite")
            rows.append((module, len(names), white, nonwhite, len(names) - white - nonwhite))
        rows.sort(key=lambda r: (-r[1], r[0].lower()))
        return rows

    _module_names: dict[str, set[str]] = field(default_factory=dict)

    def add(self, name: str, module: str, database: str) -> None:
        symbol = self.symbols.setdefault(name, ImportedSymbol(name))
        symbol.modules.add(module)
        symbol.databases.add(database)
        self._module_names.setdefault(module, set()).add(name)


def _read_export_json(path: Path) -> list[dict] | None:
    """Импорты из артефакта «Анализа ПО»; None, если файл не подходит."""
    try:
        with open(path, "r", encoding="utf-8") as handle:
            data = json.load(handle)
    except (OSError, ValueError):
        return None
    imports = data.get("imports")
    return imports if isinstance(imports, list) else None


def _db_files_for(db: Path) -> list[Path]:
    """Файлы базы (для .idb — вместе с .id0/.id1/.nam/.til)."""
    files = [db]
    base = str(db)
    for suffix in (".id0", ".id1", ".nam", ".til"):
        extra = Path(base[:-len(db.suffix)] + suffix)
        if extra.exists():
            files.append(extra)
    return files


def _imports_via_ida(db: Path, idat: Path, timeout: int = 1800) -> dict[str, list[str]]:
    """Открывает копию базы в IDA и выгружает таблицу импорта."""
    workdir = Path(tempfile.mkdtemp(prefix="osslwh-"))
    try:
        local_db = workdir / db.name
        for src in _db_files_for(db):
            shutil.copy2(src, workdir / src.name)
        script = workdir / "dump_imports.py"
        script.write_text(_IDA_IMPORTS_SCRIPT, encoding="utf-8")
        out_path = workdir / "imports.json"
        log_path = workdir / "ida.log"
        script_cmd = f'"{script}" "{out_path}"'
        subprocess.run(
            [str(idat), "-A", f"-S{script_cmd}", f"-L{log_path}", str(local_db)],
            check=False, capture_output=True, timeout=timeout,
        )
        if not out_path.exists():
            log_tail = ""
            if log_path.exists():
                log_tail = log_path.read_text(encoding="utf-8", errors="replace")[-400:]
            raise RuntimeError(f"IDA не сформировала импорты. {log_tail}".strip())
        with open(out_path, "r", encoding="utf-8") as handle:
            data = json.load(handle)
        return {str(k): [str(x) for x in v] for k, v in data.items()}
    finally:
        shutil.rmtree(workdir, ignore_errors=True)


def find_idat(explicit: str | None = None) -> Path | None:
    """Ищет idat64.exe/idat.exe: параметр, config.yaml, env, Program Files, PATH."""
    if explicit:
        path = Path(explicit)
        if path.is_dir():
            for name in ("idat64.exe", "idat.exe"):
                if (path / name).exists():
                    return path / name
        elif path.exists():
            return path

    candidates: list[Path] = []
    for key in ("IDAT_PATH", "IDA_PATH", "IDA_DIR"):
        value = os.environ.get(key)
        if value:
            candidates.append(Path(value))

    # Рядом с поставкой: tools\ossl-whitelist -> app\config.yaml
    config = Path(__file__).resolve().parent.parent.parent / "app" / "config.yaml"
    if config.exists():
        try:
            text = config.read_text(encoding="utf-8", errors="replace")
            match = re.search(r"^\s*executable:\s*(.+?)\s*$", text, re.M)
            if match:
                candidates.append(Path(match.group(1).strip().strip("'\"")))
        except OSError:
            pass

    for root in (os.environ.get("ProgramFiles"), os.environ.get("ProgramFiles(x86)")):
        if root:
            candidates.extend(sorted(Path(root).glob("IDA*/idat64.exe"), reverse=True))
            candidates.extend(sorted(Path(root).glob("IDA*/idat.exe"), reverse=True))

    for candidate in candidates:
        if candidate.is_dir():
            for name in ("idat64.exe", "idat.exe"):
                if (candidate / name).exists():
                    return candidate / name
        elif candidate.exists():
            return candidate

    for name in ("idat64.exe", "idat.exe"):
        found = shutil.which(name)
        if found:
            return Path(found)
    return None


def _iter_units(root: Path) -> list[tuple[Path | None, Path | None]]:
    """Пары (база, export.json) для папки, включая осиротевшие json."""
    seen_dirs: set[str] = set()
    dbs: dict[str, Path] = {}
    jsons: dict[str, Path] = {}
    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        real = os.path.realpath(dirpath)
        if real in seen_dirs:
            dirnames[:] = []
            continue
        seen_dirs.add(real)
        dirnames[:] = sorted(d for d in dirnames if not d.startswith("."))
        for filename in sorted(filenames):
            path = Path(dirpath) / filename
            lower = filename.lower()
            if lower.endswith(JSON_SUFFIX) and lower.endswith(tuple(s + JSON_SUFFIX for s in DB_SUFFIXES)):
                jsons[str(path)[:-len(JSON_SUFFIX)]] = path
            elif lower.endswith(DB_SUFFIXES):
                dbs[str(path)] = path

    units: list[tuple[Path | None, Path | None]] = []
    for key in sorted(set(dbs) | set(jsons), key=str.lower):
        units.append((dbs.get(key), jsons.get(key)))
    return units


def collect_imports(
    root: Path,
    idat: Path | None,
    force_ida: bool = False,
    jobs: int = DEFAULT_JOBS,
    progress=None,
    should_stop=None,
) -> ImportScan:
    """Собирает импорты всех баз каталога и объединяет их."""
    scan = ImportScan(root=root)
    units = _iter_units(root)
    total = len(units)
    done = 0

    pending_ida: list[tuple[Path, UnitInfo]] = []
    for db, json_path in units:
        if should_stop and should_stop():
            break
        info = UnitInfo(path=db or json_path, source="error")
        imports = None
        if json_path is not None and not force_ida:
            imports = _read_export_json(json_path)
            if imports is not None:
                info.source = "json"
        if imports is not None:
            for item in imports:
                raw = str(item.get("name") or "")
                if not raw:
                    continue
                name = normalize_symbol(raw)
                module = str(item.get("module") or "unknown")
                scan.add(name, module, info.path.name)
            info.imports = len(imports)
            scan.units.append(info)
            done += 1
            if progress:
                progress(done, total, info.path.name)
        elif db is not None:
            pending_ida.append((db, info))
        else:
            info.error = "нет базы и нет пригодного export.json"
            scan.units.append(info)
            done += 1
            if progress:
                progress(done, total, info.path.name)

    if pending_ida and idat is None:
        for _, info in pending_ida:
            info.error = "не найден idat.exe (укажите путь к IDA)"
            scan.units.append(info)
            done += 1
            if progress:
                progress(done, total, info.path.name)
        pending_ida = []

    def run_one(item: tuple[Path, UnitInfo]) -> UnitInfo:
        db, info = item
        try:
            data = _imports_via_ida(db, idat)  # type: ignore[arg-type]
        except Exception as exc:  # noqa: BLE001 - причина уходит в отчёт
            info.source = "error"
            info.error = f"{type(exc).__name__}: {exc}"
            return info
        count = 0
        for module, names in data.items():
            for raw in names:
                name = normalize_symbol(raw)
                if name:
                    scan.add(name, module, db.name)
                    count += 1
        info.source = "ida"
        info.imports = count
        return info

    if pending_ida:
        workers = max(1, min(int(jobs or 1), len(pending_ida)))
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
            futures = {pool.submit(run_one, item): item for item in pending_ida}
            for future in concurrent.futures.as_completed(futures):
                if should_stop and should_stop():
                    break
                info = future.result()
                scan.units.append(info)
                done += 1
                if progress:
                    progress(done, total, info.path.name)

    return scan


